import backtrader as bt


class RSIBandsMeanReversionStrategy(bt.Strategy):
    params = dict(
        rsi_period=14,
        band_period=20,
        band_dev=2,
        stop_pct=0.02,
    )

    def __init__(self):
        self.rsi = bt.indicators.RSI(self.data, period=self.p.rsi_period)
        self.rsi_sma = bt.indicators.SMA(self.rsi, period=self.p.band_period)
        self.rsi_std = bt.indicators.StdDev(self.rsi, period=self.p.band_period)
        self.upper_band = self.rsi_sma + self.p.band_dev * self.rsi_std
        self.lower_band = self.rsi_sma - self.p.band_dev * self.rsi_std
        self.crossover = bt.indicators.CrossOver(self.rsi, self.rsi_sma)

        self.order = None
        self.stop_order = None
        self.long_armed = False
        self.short_armed = False

    def notify_order(self, order):
        if order.status in (order.Submitted, order.Accepted):
            return

        if order.status == order.Completed:
            if order is self.order:
                if not self.position:
                    self.order = None
                    self.stop_order = None
                else:
                    entry_price = order.executed.price
                    if order.isbuy():
                        stop_price = entry_price * (1 - self.p.stop_pct)
                        self.stop_order = self.sell(
                            exectype=bt.Order.Stop,
                            price=stop_price,
                            size=self.position.size,
                        )
                    else:
                        stop_price = entry_price * (1 + self.p.stop_pct)
                        self.stop_order = self.buy(
                            exectype=bt.Order.Stop,
                            price=stop_price,
                            size=abs(self.position.size),
                        )
                    self.order = None
            elif order is self.stop_order:
                self.stop_order = None
                self.order = None
        elif order.status in (order.Canceled, order.Margin, order.Rejected):
            if order is self.order:
                self.order = None
            if order is self.stop_order:
                self.stop_order = None

    def next(self):
        if self.order:
            return

        if not self.position:
            if self.rsi[0] < self.lower_band[0]:
                self.long_armed = True
            if self.rsi[0] > self.upper_band[0]:
                self.short_armed = True

            if self.long_armed and self.crossover[0] > 0:
                self.order = self.buy()
                self.long_armed = False
                self.short_armed = False
            elif self.short_armed and self.crossover[0] < 0:
                self.order = self.sell()
                self.long_armed = False
                self.short_armed = False
        else:
            if self.position.size > 0 and self.crossover[0] < 0:
                if self.stop_order:
                    self.cancel(self.stop_order)
                self.order = self.close()
            elif self.position.size < 0 and self.crossover[0] > 0:
                if self.stop_order:
                    self.cancel(self.stop_order)
                self.order = self.close()
